&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;12,1,0&quot;&gt;&lt;strong data-path-to-node=&quot;12,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Frontend :&lt;/strong&gt; React, Next.js&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;12,2,0&quot;&gt;&lt;strong data-path-to-node=&quot;12,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Bases de données :&lt;/strong&gt; PostgreSQL, MongoDB&lt;/p&gt;
&lt;/li&gt;
